"""Dashboard freshness and error presentation; all labels use the panel language."""
DASHBOARD_CSS = """
#refreshError{padding:14px 18px;margin:16px 0;border-left:4px solid var(--acc);background:var(--soft);border-radius:10px}#refreshError[hidden]{display:none}.reading-age{font-size:12px;color:var(--mut);margin-top:8px}.bike-photo summary{cursor:pointer;font-size:13px;color:var(--mut);margin-top:18px}.bike-photo .bike{max-height:190px}.bike-photo .bikewrap{margin:12px 0}.ride-select{font:inherit;color:var(--acc);background:transparent;padding:0;margin:0;border:0;text-align:left;text-decoration:underline}.ride-chart rect[role=button]{cursor:pointer}.ride-chart rect:focus{stroke:var(--ink);stroke-width:2}.trend-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:18px}.trend-grid svg{width:100%;height:90px}.trend-grid small{display:block;color:var(--mut);line-height:1.6}.dashboard-shortcuts{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.dashboard-shortcuts button{font-size:12px;margin:0;padding:8px 12px}@media(max-width:520px){.trend-grid{grid-template-columns:1fr}.hero{padding:22px 18px}}
"""
DASHBOARD_SCRIPT = r"""
function readingAge(value){return value?ago(value):it('Meettijd onbekend','Measurement time unknown');}
function trackerReading(L){const candidates=[{value:L.tracker_battery,at:L.tracker_updated,source:'Bluetooth'},{value:L.cloud&&L.cloud.module_charge,at:L.cloud&&L.cloud.ts,source:it('Cloud','Cloud')}].filter(r=>finite(r.value)&&r.value>=0&&r.value<=100).map(r=>({...r,time:Date.parse(r.at)}));candidates.sort((a,b)=>(Number.isFinite(b.time)?b.time:-Infinity)-(Number.isFinite(a.time)?a.time:-Infinity));return candidates[0]||null;}
function renderDashboardState(s){const L=s.last||{},I=L.insights||{},C=I.connection||{},state=C.state||'starting';const labels={reading_ok:it('Recent uitgelezen','Recently read'),connecting:it('Bezig met uitlezen','Reading bike'),off_or_out_of_range:it('Fiets uit of buiten bereik','Bike off or out of range'),pairing_required:it('Koppelen nodig','Pairing required'),not_paired:it('Koppelen nodig','Pairing required'),receiver_unavailable:it('Bluetooth-ontvanger niet beschikbaar','Bluetooth receiver unavailable'),read_failed:it('Uitlezen mislukt','Read failed'),stale:it('Laatste gegevens verouderd','Last readings are stale'),no_bike:it('Geen fiets gekoppeld','No bike selected'),starting:it('Wachten op uitlezing','Waiting for a reading')};const label=labels[state]||labels.starting;for(const id of ['conn','addedConn']){const el=$('#'+id);el.textContent=label;el.className='badge'+(state==='reading_ok'?' on':'');}$('#bikeSpec').textContent=it('Bluetooth · Laatste uitlezing: ','Bluetooth · Last read: ')+(L.last_updated?ago(L.last_updated):it('nog geen','none yet'));for(const [id,key] of [['modeAge','mode_updated'],['rangeAge','range_updated']]){$('#'+id).textContent=it('Laatst bekend · ','Last known · ')+readingAge(L[key]);}const r=trackerReading(L);$('#gpsBatt').textContent=r?inum(r.value,0)+'%':'—';$('#gpsUpd').textContent=r?r.source+' · '+readingAge(r.at):it('Nog geen meting','No reading yet');const proxy=s.proxy||{};$('#proxyHelp').textContent=proxy.configured?(proxy.connected?it('Proxy bereikbaar. ','Proxy reachable. '):it('Proxy niet verbonden. ','Proxy disconnected. '))+it('Deze proxy luistert naar de tracker; fietsgegevens worden via de lokale Bluetooth-adapter gelezen.','This proxy listens for the tracker; bike data is read through the local Bluetooth adapter.'):it('Geen trackerproxy ingesteld. Fietsgegevens gebruiken de lokale Bluetooth-adapter.','No tracker proxy configured. Bike data uses the local Bluetooth adapter.');$('#photoSummary').textContent=it('Bekijk de fiets','View bike');$('#quickBattery').textContent=it('Accu-inzicht','Battery insights');$('#quickRides').textContent=it('Mijn ritten','My rides');$('#quickConnection').textContent=it('Verbindingshulp','Connection help');}
let refreshFlight=null;
function showRefreshError(){const box=$('#refreshError');box.hidden=false;$('#refreshErrorText').textContent=it('Verversen mislukt. Je ziet de laatst ontvangen gegevens. Controleer of de add-on actief is.','Refresh failed. Showing the last received data. Check that the add-on is running.');$('#refreshRetry').textContent=it('Opnieuw proberen','Try again');}
async function refresh(){if(refreshFlight)return refreshFlight;refreshFlight=(async()=>{try{const focused=document.activeElement&&document.activeElement.id;await refreshData();if(focused&&document.getElementById(focused)&&document.activeElement.id!==focused)document.getElementById(focused).focus({preventScroll:true});$('#refreshError').hidden=true;}catch(e){showRefreshError();}finally{refreshFlight=null;}})();return refreshFlight;}
function renderRideDetail(index){const rows=filteredRides(),r=rows[index];if(!r)return;selectedRideEnd=r.end;const el=$('#rideDetail');el.hidden=false;el.textContent=new Date(r.end*1000).toLocaleString(LANG)+' · '+inum(r.km)+it(' km · ',' km · ')+(r.quality==='interval'?it('Meetinterval: kan meerdere ritten bevatten.','Measurement interval: may contain multiple rides.'):it('Geschatte rit.','Inferred ride.'))+' '+(finite(r.battery_drop)?it('Accuverbruik: ','Battery used: ')+inum(r.battery_drop)+it(' procentpunt.',' percentage points.'):it('Geen betrouwbaar accuverbruik beschikbaar.','No reliable battery consumption available.'));}
let selectedRideEnd=null;
function renderTrends(){const points=insightData&&insightData.trends||[];const root=$('#batteryTrends');root.innerHTML='';for(const [key,nl,en,unit] of [['battery_soh','Accugezondheid','Battery health','%'],['battery_cycles','Laadcycli','Charge cycles','']]){const rows=points.filter(p=>finite(p.at)&&finite(p[key]));const card=document.createElement('div'),title=document.createElement('strong');title.textContent=it(nl,en);card.appendChild(title);if(rows.length<2){const note=document.createElement('small');note.textContent=it('Trend verschijnt na metingen op minstens twee dagen.','Trend appears after measurements on at least two days.');card.appendChild(note);}else{const lo=Math.min(...rows.map(p=>p[key])),hi=Math.max(...rows.map(p=>p[key])),span=Math.max(1,hi-lo),first=rows[0],last=rows[rows.length-1],dt=Math.max(1,last.at-first.at);const coords=rows.map(p=>(5+(p.at-first.at)/dt*290)+','+(75-(p[key]-lo)/span*60)).join(' ');card.innerHTML+='<svg viewBox="0 0 300 90" role="img" aria-label="'+esc(it(nl,en))+'"><polyline fill="none" stroke="var(--acc)" stroke-width="2" points="'+coords+'"/></svg>';const note=document.createElement('small');note.textContent=inum(first[key])+unit+' → '+inum(last[key])+unit+' · '+new Date(first.at*1000).toLocaleDateString(LANG)+' – '+new Date(last.at*1000).toLocaleDateString(LANG)+' · '+rows.length+it(' meetdagen',' measurement days');card.appendChild(note);}root.appendChild(card);}}
"""
